#!/usr/bin/env python3
"""Phase-10 domain set: generated by a fixed rule, not chosen by inspection.

Protocol: docs/PROTOCOL_PHASE10_ANALYSIS_IRRECOVERABILITY.md.

Rule (frozen before any Phase-10 data were retrieved):
1. Tile the globe with 20 deg x 40 deg boxes on a fixed lattice: latitude
   bands with northern edges at 55N, 35N, 15N, 5S, 25S, and longitude edges
   every 40 deg starting at 20E. 45 boxes. The 20E offset is a technical
   choice fixed in advance: it places a lattice edge exactly on 180 deg, so
   that no domain straddles the antimeridian and every request can be
   expressed in the [-180, 180] convention the archives require.
2. Drop any box whose area overlaps an existing programme region by more
   than 20 %.
3. Keep every survivor. No box is added, moved or removed for any other
   reason.

The rule leaves 27 new domains. They are named by their own bounds so that
no regime label enters through the name.
"""

from __future__ import annotations

import sys
from pathlib import Path

import numpy as np

_HERE = Path(__file__).resolve().parent
for _p in (str(_HERE), str(_HERE.parent)):
    if _p not in sys.path:
        sys.path.insert(0, _p)

try:
    import clean_experiments.download_b1_era5_wind as _b1
    from clean_experiments.download_b2_era5_wind import REGIONS_B2 as _R2
    from clean_experiments.download_b2b_era5_wind import REGIONS_B2B as _R2B
except ImportError:  # pragma: no cover
    import download_b1_era5_wind as _b1  # type: ignore
    from download_b2_era5_wind import REGIONS_B2 as _R2  # type: ignore
    from download_b2b_era5_wind import REGIONS_B2B as _R2B  # type: ignore

REGIONS_EXISTING = {**_b1.REGIONS, **_R2, **_R2B}

LAT_BANDS = [(55.0, 35.0), (35.0, 15.0), (15.0, -5.0), (-5.0, -25.0),
             (-25.0, -45.0)]
LON_EDGES = [(float(l % 360), float((l + 40) % 360 or 360.0))
             for l in range(20, 380, 40)]
MAX_OVERLAP = 0.20


def _lon_overlap_deg(w1: float, e1: float, w2: float, e2: float) -> float:
    grid = np.arange(0.0, 360.0, 0.5)

    def mask(w: float, e: float) -> np.ndarray:
        return (grid >= w) & (grid < e) if w < e else ((grid >= w) | (grid < e))

    return float((mask(w1, e1) & mask(w2, e2)).sum()) * 0.5


def _overlap_fraction(a: tuple, b: tuple) -> float:
    n1, w1, s1, e1 = a
    n2, w2, s2, e2 = b
    lat = max(0.0, min(n1, n2) - max(s1, s2))
    lon = _lon_overlap_deg((w1 + 360) % 360, (e1 + 360) % 360,
                           (w2 + 360) % 360, (e2 + 360) % 360)
    return (lat * lon) / ((n1 - s1) * (e1 - w1 if e1 > w1 else e1 + 360 - w1))


def _label(north: float, west: float) -> str:
    ns = f"{abs(north):.0f}{'N' if north >= 0 else 'S'}"
    w = west - 360.0 if west >= 180 else west
    ew = f"{abs(w):.0f}{'E' if w >= 0 else 'W'}"
    return f"{ns}{ew}"


def build_regions() -> dict[str, list[float]]:
    out: dict[str, list[float]] = {}
    k = 0
    for north, south in LAT_BANDS:
        for west, east in LON_EDGES:
            cand = (north, west, south, east)
            worst = max(_overlap_fraction(cand, tuple(v))
                        for v in REGIONS_EXISTING.values())
            if worst > MAX_OVERLAP:
                continue
            k += 1
            # CDS wants west/east in [-180, 180]; a western edge exactly on
            # the antimeridian is expressed as -180, an eastern edge as +180.
            w = west - 360.0 if west >= 180 else west
            e = east - 360.0 if east > 180 else east
            out[f"G{k:02d}_{_label(north, west)}"] = [north, w, south, e]
    return out


REGIONS_B10 = build_regions()

WINDOWS_B10 = {
    "W11_2024JFM": ("2024", ["01", "02", "03"]),
    "W12_2024JAS": ("2024", ["07", "08", "09"]),
}


if __name__ == "__main__":
    for name, area in REGIONS_B10.items():
        print(f"{name:>16}  N {area[0]:>5}  W {area[1]:>6}  S {area[2]:>5}  E {area[3]:>6}")
    print(f"n = {len(REGIONS_B10)}")
